        category: .violent,
        headlines: ["Man Cuts Bull Rider After Dispute at Feed Store", "Defendant From Rodeo Stabbing Case Back in Court"],
        law: "awdw",
        spec: "Assaulted {V} with a deadly weapon, a knife, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a bull rider was cut on the forearm at a feed store after a dispute about a horse. {DL} says {V} grabbed {D.him} first.",
