        defense: [E(.statement, 1, "Grab", "{DL} says {V} grabbed {D.him}.")],
        role: "Feed store clerk",
        exam: [.direct("What is your job?", "\"I'm a clerk at a feed store, and I was working the counter when the incident happened.\""), .direct("What happened that day?", "\"Two men came in arguing about a horse that one of them said was sold wrong, and the argument got louder.\""), .direct("What did {DL} do?", "\"{D.He} took out a knife, swung it at the other man, and cut {V.him} on the forearm.\""), .direct("Who was the other man?", "\"{V}, a bull rider I've known for years, who stepped back holding {D.his} arm and bleeding.\""), .direct("What does the store camera show?", "\"It shows {DL} and {V} arguing, {V} reaching out, and {DL} swinging a blade in one fast motion.\""), .direct("What did you do?", "\"I called 911 and gave {V} a towel, and I told {DL} to stay until deputies came.\""), .cross("{V} grabbed {DL} first?", "\"{D.He} reached out and touched {D.his} arm, but I couldn't tell if {D.he} grabbed or just pointed.\""), .cross("The knife was small?", "\"It was a small pocket knife, with a blade of about three inches that folds into the handle.\""), .cross("{DL} left the store?", "\"{D.He} walked out and was found in the parking lot.\""), .cross("The two knew each other?", "\"Yes, they knew each other from rodeo events and had competed against each other for years.\""), .cross("The cut needed stitches?", "\"I think so. The paramedics wrapped it and took {D.him} in.\"")],
        theory: ("{D} cut a rider.", "A defense."),
        allocution: "\"{V} grabbed me first, and I reacted at that feed store in a way I regret. I know I was in this court once before, and I promised myself I'd stay out of trouble. I've thought hard about it, and I'll walk away from the next argument.\"",
        truths: ("{DL} had a prior knife case in this court.", "{V}'s hand was on {DL}'s collar."),
        defendant: [.direct("Did you cut {V}?", "\"Yes, I cut {V.him}. {V.He} grabbed my arm during the argument, and I reacted with my knife.\""), .direct("Why did you have a knife?", "\"I carry a pocket knife for work with the horses. It's always in my pocket.\""), .direct("Why did you pull it out?", "\"{V.He} grabbed me hard and I thought {V.he}'d hit me. I swung without thinking.\""), .direct("Did you mean to hurt {V.him}?", "\"No. I meant to make {V.him} let go. I didn't think the blade would cut {V.him}.\""), .direct("What did you do after?", "\"I walked out and stood by my truck, shaken. A deputy found me and I told him what happened.\""), .direct("What would you tell {V}?", "\"I'm sorry I hurt you. I'll pay your medical bills, and I won't come near you.\""), .cross("You were in court for fighting before, weren't you?", "\"Yes, and I told the judge I'd walk away. I didn't walk away.\""), .cross("You swung a knife at a man's arm?", "\"I did that, and I regret it more than I can say.\""), .cross("{V.He} grabbed you, but did {V.he} have a weapon?", "\"No, {V.he} had nothing in {V.his} hands.\""), .cross("You could have stepped back?", "\"I could have, and that's the choice I keep thinking about.\""), .cross("You'll avoid carrying the knife into stores?", "\"Yes, I'll leave it in the truck.\"")],
        openings: ("A feed store clerk watched two men argue over a horse that one said was sold wrong, the argument grew louder, and {D} swung a blade at {V}, cutting the bull rider's forearm, as the store camera and a medical report show, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say {V} grabbed {D} first, and {D} swung the blade only to break free. A man who is seized by the arm may defend himself, and {D} did not pursue {V}."),
