        category: .robbery,
        headlines: ["Quarry Office Robbed at Gunpoint on Payday", "Voice Again Identified by Clerk"],
        law: "dangerousRobbery",
        spec: "Took $15,000 belonging to {V} by endangering and threatening {V.his} life with a firearm, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a quarry office clerk was robbed at gunpoint on payday. The clerk again recognized a voice. {DL} says {D.he} was at home.",
        state: [E(.statement, 3, "Clerk", "'That's {D}'s voice.'"), E(.digital, 2, "Phone Location", "{DL}'s phone off from 6 to 9.")],
        defense: [E(.statement, 1, "Home", "{DL} says {D.he} was at home.")],
        role: "Quarry clerk",
        exam: [.direct("What is your job?", "\"I'm the office clerk at a quarry, and I handle payroll and cash on the days we pay the crews.\""), .direct("What happened on payday?", "\"A man came into the office, pointed a gun at me, and demanded the cash box with the payroll.\""), .direct("How much was taken?", "\"Fifteen thousand dollars in cash that I had counted and sealed in envelopes for the workers.\""), .direct("How did you identify the man?", "\"{D.He} wore a mask and kept {D.his} voice low, but I recognized it right away as {DL}'s voice.\""), .direct("How do you know {DL}'s voice?", "\"{D.He} worked at the quarry until a few months ago, and I spoke with {D.him} nearly every payday.\""), .direct("What did the phone data show?", "\"{DL}'s phone was turned off from six to nine that evening, covering the time of the robbery.\""), .cross("The man wore a mask?", "\"Yes, a dark ski mask, and gloves.\""), .cross("You only heard the voice?", "\"I heard it clearly and for several minutes, while I opened the box and handed over the cash.\""), .cross("A voice can be disguised?", "\"It can, but this wasn't disguised, and I knew it.\""), .cross("{DL} left the quarry on bad terms?", "\"{D.He} was let go after a safety violation, and {D.he} was angry.\""), .cross("The gun was real?", "\"I believe so, but I couldn't swear to it. It was pointed straight at me.\"")],
        theory: ("{D} robbed a clerk.", "An alibi."),
        allocution: "\"I was home that day, and my phone battery had died. I understand why the clerk thought the voice was mine, and I'm sorry for the fear anyone felt at that quarry. I've been in this court before and I know how that looks.\"",
        truths: ("{DL} had a prior case in this court.", "A neighbor saw {DL}'s truck at home."),
        defendant: [.direct("Were you at the quarry that day?", "\"No. I was at home, and I haven't been to the quarry since I was let go.\""), .direct("Why was your phone off?", "\"I turned it off to save battery and because I was tired. I went to bed early that night.\""), .direct("Did you rob the office?", "\"No, I did not. I've never had a gun in my hands in that place.\""), .direct("Why would the clerk say it was your voice?", "\"{V.He} knows me, and I'm the one who left on bad terms. I understand why {V.he} thinks of me.\""), .direct("Who can say you were home?", "\"My wife was there, and a neighbor saw me taking out the trash around seven.\""), .direct("What would you tell the clerk?", "\"I'm sorry you went through that. I wish I could tell you who did it, but it wasn't me.\""), .cross("You've been charged with a robbery before, haven't you?", "\"Yes, and I took my punishment for that one. I'm not that man anymore.\""), .cross("Your phone was off during the robbery?", "\"It was, and I know that looks bad. It's something I do at night.\""), .cross("Your wife may say what you ask her to?", "\"She'll tell the truth, and the neighbor will too.\""), .cross("You were angry about being fired?", "\"I was, but anger isn't the same as robbing someone.\""), .cross("You'll let deputies check your home?", "\"Yes, any time, and I'll hand over my phone.\"")],
        openings: ("A quarry office clerk who handles payroll was robbed at gunpoint on payday by a man who demanded the cash box, and the clerk again recognized a voice, saying 'That's {D}'s voice.' {D}'s phone was off from six to nine, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {D} was at home that evening and that a voice heard once under fear is an unreliable thing to rely on. {D} did not rob anyone."),
        closings: ("The clerk knows {D}'s voice from the earlier case over {PRIOR}, the robber's voice was the same, and {D}'s phone was switched off for the whole window of the robbery.", "A voice remembered from a frightening moment is not a certain identification, and a phone switched off is not an admission. The State must prove {D} was the man with the gun."),
        timeline: [(0, "8 a.m.: the robbery."), (0, "8:15 a.m.: the 911 call.")],
        identified: "A voice.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided)

    static let boxCutterAgain = SmallCases.make(
