        exam: [.direct("What is your job?", "\"I'm a clerk at a corner store, and I work the counter in the evenings.\""), .direct("What happened that night?", "\"A man in a gray cap came to the counter, pulled out a box cutter, and told me to open the register.\""), .direct("What did you do?", "\"I opened it and gave him all the cash I could grab, and he took two hundred ninety dollars.\""), .direct("What did the man look like?", "\"About six feet tall, a gray cap pulled low, a dark jacket, and a bandanna over the lower part of {D.his} face.\""), .direct("What does the store camera show?", "\"It shows the man in the gray cap raising a box cutter at me, taking the cash, and running out.\""), .direct("What was found later?", "\"A gray cap in {DL}'s truck, matching the one on the video, when deputies searched it under a warrant.\""), .cross("The man's face was covered?", "\"Mostly, with the bandanna up to {D.his} nose.\""), .cross("You couldn't identify {DL}?", "\"No, not by face. I only saw the eyes and the hat.\""), .cross("Gray caps are common?", "\"Yes, many people in this county wear gray caps like that one, especially working men.\""), .cross("The cap in the truck has a logo?", "\"Yes, a small one, and it's the same on the video.\""), .cross("The man didn't touch you?", "\"No, but {D.he} held the box cutter close to my face.\"")],
        theory: ("{D} robbed a clerk.", "A common cap."),
        allocution: "\"I did not rob that store, and that cap is a common one that my friends wear too. I was in this court before, and I know that doesn't help me. I'm sorry for the fear the clerk went through. I stand by what I told you, and I'm asking the court to look at the evidence.\"",
        truths: ("{DL} had a prior case in this court.", "Three friends own the same cap."),
        defendant: [.direct("Do you own a gray cap?", "\"Yes, I own one. I bought it at a farm store, and a lot of people have caps like it.\""), .direct("Why was it in your truck?", "\"I keep it on the dash for the sun. It's been there for weeks.\""), .direct("Did you rob the store?", "\"No. I wasn't at that store that night. I was at home with my family.\""), .direct("Where were you that night?", "\"At home with my wife and two kids, and we watched a show together.\""), .direct("Why would the video look like you?", "\"I'm tall and wear a cap like that, so I can see why the deputies thought of me.\""), .direct("What would you tell the clerk?", "\"I'm sorry for everything you went through that day. It wasn't me, and I hope they find the man.\""), .cross("You've been charged with robbery before, haven't you?", "\"Yes, and I paid for it. I'm not doing that again.\""), .cross("The cap matches the video?", "\"It looks the same, and so do thousands of others.\""), .cross("Your wife is your alibi?", "\"She is, and so are my kids and a neighbor who saw me.\""), .cross("You were near that store earlier?", "\"I passed it on the way home, as I do most days.\""), .cross("You'll provide your phone records?", "\"Yes, and any photos from that night.\"")],
        openings: ("A corner store clerk working the evening counter was told to open the register by a man in a gray cap who pulled out a box cutter, and the store camera shows a man in a gray cap raise a box cutter, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say gray caps are common and thousands of men own one just like it. A cap on a camera does not name a robber, and the man's face is covered."),
        closings: ("The camera shows a man in a gray cap raise a box cutter at the counter, the cap matches the one linked to {D}, and after {PRIOR} {DL} understood exactly what that cap and that blade mean.", "A common cap does not make {D} the robber, and the camera shows no face. The State must prove {D} was the man behind the counter that night."),
