        defense: [E(.document, 1, "Bridge Note", "A repayment note.")],
        role: "Closing attorney",
        exam: [.direct("What is your role?", "\"I'm a closing attorney, and I handle real estate closings and hold funds in escrow until the sale is done.\""), .direct("What happened with this closing?", "\"The buyer's twenty-six thousand dollar deposit was supposed to be in escrow, but when I went to close, the money was gone.\""), .direct("What do the bank records show?", "\"Twenty-six thousand dollars moved from the escrow account into {DL}'s personal account a week before closing.\""), .direct("Who held the funds?", "\"{DL}, who was the escrow agent under the agreement, and who signed a statement acknowledging the funds.\""), .direct("What was the effect?", "\"The closing failed, and the buyer lost the house, and the seller sued.\""), .direct("What did {DL} say?", "\"{D.He} said it was a temporary transfer to cover another closing and that {D.he} would put it back.\""), .cross("{DL} was authorized to hold the funds?", "\"Yes, but not to use them for any other purpose.\""), .cross("{DL} had a repayment note?", "\"A note exists, but it's unsigned and dated after the transfer.\""), .cross("{DL} returned some money?", "\"Eventually, about half of it came back, but only after the closing had already failed.\""), .cross("{DL} has a good reputation?", "\"Until this, yes, {D.he} had an excellent reputation in the local real estate community.\""), .cross("The seller and buyer lost money?", "\"Yes, in fees and interest, and the buyer lost the contract.\"")],
        theory: ("{D} took escrow.", "A bridge."),
        allocution: "\"That money was a temporary bridge, and I meant to repay it to the account before anyone noticed. I know I stood in this court once before. I'm sorry that a family's closing fell through because of it. I'll make the escrow whole.\"",
        truths: ("{DL} had a prior case in this court.", "The brokerage covered the shortfall."),
        defendant: [.direct("Did you move the money?", "\"Yes, I moved it. I needed to cover another closing that was short, and I thought I'd put it back in a few days.\""), .direct("Why did you need the money?", "\"A different closing was short because a buyer's wire was delayed. I borrowed from this one to keep it on track.\""), .direct("Did you plan to keep it?", "\"No. I planned to return it as soon as the wire arrived. It didn't come as quickly as I expected.\""), .direct("Why didn't you tell anyone?", "\"I was ashamed. I thought I'd fix it before anyone noticed, and I made it worse.\""), .direct("What happened to the closing?", "\"It fell through because I couldn't replace the money in time. I feel terrible about the buyer.\""), .direct("What would you tell the buyer and seller?", "\"I'm sorry for the harm I caused. I'll repay every dollar and any fees you lost.\""), .cross("You've been disciplined by the bar before, haven't you?", "\"Yes, and I promised to be careful. I broke that promise.\""), .cross("You moved trust funds to your own account?", "\"I did, and I know I shouldn't have.\""), .cross("The note is dated after the transfer?", "\"Yes, I wrote it later, and I regret that.\""), .cross("You'll repay twenty-six thousand dollars?", "\"Yes, I'll repay it on a schedule that the court and the bar approve.\""), .cross("You'll give up your license?", "\"If the bar requires it, yes.\"")],
