        exam: [.direct("What is your position?", "\"I'm an auto theft investigator, and I helped execute a search warrant at a repair shop after a tip about stolen vans.\""), .direct("What did you find inside?", "\"Four cargo vans with their identification numbers ground off, partly stripped of seats, doors, and engine parts.\""), .direct("Why were the numbers ground off?", "\"Thieves do that so a vehicle can't be traced to its owner, and it's a strong sign the vans were stolen.\""), .direct("What was the value?", "\"More than forty thousand dollars in vehicles and loose parts, which we matched to four thefts in the past two months.\""), .direct("Who owns the shop?", "\"{DL}. The lease and the county records list {D.him} as the owner of the building and the business.\""), .direct("What did {DL} say?", "\"{D.He} said a tenant used the back bays and that {D.he} didn't know the vans were there.\""), .cross("The tenant lease is unsigned?", "\"Yes, a one-page lease with a first name and no signature or date, found in a drawer in the office.\""), .cross("{DL} was not at the shop during the search?", "\"{D.He} arrived about twenty minutes after we began, and {D.he} was surprised and upset when {D.he} saw the vans.\""), .cross("No stolen parts were found in the front office?", "\"The front looked like an ordinary repair counter, with customer cars and normal tools.\""), .cross("You haven't located the tenant?", "\"Not yet, though {DL} says {D.he} can give us a phone number and a description.\""), .cross("Other people had keys to the back?", "\"The employees said several people could get in, including a man who wasn't on the payroll.\"")],
